#include <string.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 2048

typedef float v8 __attribute__((vector_size(32), aligned(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static float Apack[MC * KC] __attribute__((aligned(64)));
static float Bpack[KC * NC] __attribute__((aligned(64)));

/* Pack a kc x nc block of B into NR-wide column strips, zero-padded. */
static void pack_B(int kc, int nc, const float *B, int ldb, float *Bp)
{
    for (int j = 0; j < nc; j += NR) {
        int nr = nc - j < NR ? nc - j : NR;
        if (nr == NR) {
            for (int k = 0; k < kc; k++) {
                memcpy(Bp, B + (size_t)k * ldb + j, NR * sizeof(float));
                Bp += NR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                const float *src = B + (size_t)k * ldb + j;
                int c = 0;
                for (; c < nr; c++) Bp[c] = src[c];
                for (; c < NR; c++) Bp[c] = 0.0f;
                Bp += NR;
            }
        }
    }
}

/* Pack an mc x kc block of A into MR-tall row strips, zero-padded. */
static void pack_A(int mc, int kc, const float *A, int lda, float *Ap)
{
    for (int i = 0; i < mc; i += MR) {
        int mr = mc - i < MR ? mc - i : MR;
        if (mr == MR) {
            const float *a0 = A + (size_t)(i + 0) * lda;
            const float *a1 = A + (size_t)(i + 1) * lda;
            const float *a2 = A + (size_t)(i + 2) * lda;
            const float *a3 = A + (size_t)(i + 3) * lda;
            const float *a4 = A + (size_t)(i + 4) * lda;
            const float *a5 = A + (size_t)(i + 5) * lda;
            for (int k = 0; k < kc; k++) {
                Ap[0] = a0[k]; Ap[1] = a1[k]; Ap[2] = a2[k];
                Ap[3] = a3[k]; Ap[4] = a4[k]; Ap[5] = a5[k];
                Ap += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < mr; r++) Ap[r] = A[(size_t)(i + r) * lda + k];
                for (; r < MR; r++) Ap[r] = 0.0f;
                Ap += MR;
            }
        }
    }
}

/* C[mr x nr] (=|+=) Ap[MR x kc] * Bp[kc x NR] */
static void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                   float *restrict C, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(Bp);
        v8 b1 = *(const v8 *)(Bp + 8);
        float a;
        a = Ap[0]; c00 += a * b0; c01 += a * b1;
        a = Ap[1]; c10 += a * b0; c11 += a * b1;
        a = Ap[2]; c20 += a * b0; c21 += a * b1;
        a = Ap[3]; c30 += a * b0; c31 += a * b1;
        a = Ap[4]; c40 += a * b0; c41 += a * b1;
        a = Ap[5]; c50 += a * b0; c51 += a * b1;
        Ap += MR;
        Bp += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1)                                              \
        do {                                                       \
            v8u *p = (v8u *)(C + (size_t)(r) * ldc);               \
            if (first) { p[0] = x0; p[1] = x1; }                   \
            else       { p[0] += x0; p[1] += x1; }                 \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        float tmp[MR][NR] __attribute__((aligned(32)));
        *(v8 *)&tmp[0][0] = c00; *(v8 *)&tmp[0][8] = c01;
        *(v8 *)&tmp[1][0] = c10; *(v8 *)&tmp[1][8] = c11;
        *(v8 *)&tmp[2][0] = c20; *(v8 *)&tmp[2][8] = c21;
        *(v8 *)&tmp[3][0] = c30; *(v8 *)&tmp[3][8] = c31;
        *(v8 *)&tmp[4][0] = c40; *(v8 *)&tmp[4][8] = c41;
        *(v8 *)&tmp[5][0] = c50; *(v8 *)&tmp[5][8] = c51;
        for (int r = 0; r < mr; r++) {
            float *crow = C + (size_t)r * ldc;
            if (first)
                for (int c = 0; c < nr; c++) crow[c] = tmp[r][c];
            else
                for (int c = 0; c < nr; c++) crow[c] += tmp[r][c];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);
            pack_B(kc, nc, B + (size_t)pc * n + jc, n, Bpack);
            for (int ic = 0; ic < n; ic += MC) {
                int mc = n - ic < MC ? n - ic : MC;
                pack_A(mc, kc, A + (size_t)ic * n + pc, n, Apack);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *Bp = Bpack + (size_t)jr * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Apack + (size_t)ir * kc, Bp,
                               C + (size_t)(ic + ir) * n + jc + jr, n,
                               mr, nr, first);
                    }
                }
            }
        }
    }
}
